service.method:
SELECT BIZ_CODE AS SIGNER_COMPANY_CODE , BIZ_CATEGORY AS SIGNER_CATEGORY , BIZ_TYPE , SELLER_NAME_LOC AS SIGNER_COMPANY_NAME , IRS_NO , ZIP_CODE , ADDRESS_LOC AS SIGNER_COMPANY_ADDR , PHONE_NO AS SIGNER_COMPANY_PHONE_NO , EMAIL AS SIGNER_COMPANY_EMAIL , CEO_NAME_LOC AS SIGNER_COMPANY_OWNER , FOUNDATION_DATE , IF_FLAG FROM SBUPR WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND #DB_OWNER#nvl(DEL_FLAG, 'N') = 'N' AND BIZ_CATEGORY = ${BIZ_CATEGORY}
AND ( SELLER_NAME_LOC LIKE '%' + $S{F_KEYWORD} + '%' OR CEO_NAME_LOC LIKE '%' + $S{F_KEYWORD} + '%' OR IRS_NO LIKE '%' + $S{F_KEYWORD} + '%' )
AND ( BIZ_TYPE = ${BIZ_TYPE} )
